import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.Nk14N-ai.js";const p=JSON.parse('{"title":"VDF Hardware Calibration","description":"","frontmatter":{},"headers":[],"relativePath":"vdf-calibration.md","filePath":"vdf-calibration.md"}'),r={name:"vdf-calibration.md"};function n(s,e,l,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="vdf-hardware-calibration" tabindex="-1">VDF Hardware Calibration <a class="header-anchor" href="#vdf-hardware-calibration" aria-label="Permalink to &quot;VDF Hardware Calibration&quot;">​</a></h1><p>This document outlines the hardware baseline assumptions used to calibrate the Proof-of-Patience delay curves in <code>kinetic-core</code>.</p><h2 id="the-problem-with-wall-clock-time" tabindex="-1">The Problem with &quot;Wall-Clock Time&quot; <a class="header-anchor" href="#the-problem-with-wall-clock-time" aria-label="Permalink to &quot;The Problem with &quot;Wall-Clock Time&quot;&quot;">​</a></h2><p>Verifiable Delay Functions (VDFs) are measured in <strong>iterations</strong> (squarings), not seconds. The amount of real-world &quot;wall-clock time&quot; it takes to compute $N$ iterations depends entirely on the speed of the hardware evaluating the VDF.</p><p>Therefore, when the codebase or whitepaper says &quot;a 6-character name takes 8 hours,&quot; that statement is inherently tied to a specific hardware generation.</p><h2 id="the-2025-2026-baseline" tabindex="-1">The 2025/2026 Baseline <a class="header-anchor" href="#the-2025-2026-baseline" aria-label="Permalink to &quot;The 2025/2026 Baseline&quot;">​</a></h2><p>Our current scaling coefficients (implemented in <code>calculate_required_iterations</code> in <code>kinetic-core/src/types.rs</code>) are pinned to the following baseline assumption:</p><ul><li><strong>Baseline Speed:</strong> ~300,000 iterations per second (ips).</li><li><strong>Target Hardware:</strong> A mid-range, single-core consumer CPU available in 2025/2026 (e.g., Apple M2/M3 efficiency core, or an equivalent AMD/Intel core).</li><li><strong>Algorithm:</strong> Repeated squaring in ideal class groups of unknown order (via the <code>chiavdf</code> Rust bindings).</li></ul><p>At exactly 300k ips, the base iterations by name length are:</p><ul><li><code>3,000,000</code> iterations (16+ chars) ≈ 10 seconds</li><li><code>12,000,000</code> iterations (9–15 chars) ≈ 40 seconds</li><li><code>36,000,000</code> iterations (5–8 chars) ≈ 2 minutes</li><li><code>144,000,000</code> iterations (4 chars) ≈ 8 minutes</li><li><code>540,000,000</code> iterations (3 chars) ≈ 30 minutes</li><li><code>2,160,000,000</code> iterations (2 chars) ≈ 2 hours</li><li><code>8,640,000,000</code> iterations (1 char) ≈ 8 hours</li></ul><h2 id="moore-s-law-future-scaling" tabindex="-1">Moore&#39;s Law &amp; Future Scaling <a class="header-anchor" href="#moore-s-law-future-scaling" aria-label="Permalink to &quot;Moore&#39;s Law &amp; Future Scaling&quot;">​</a></h2><p>To prevent the cost floor from collapsing over time due to Moore&#39;s law or specialized ASICs, <code>kinetic-core</code> currently applies a linear offset based on the current Drand round (<code>current_drand_round</code>).</p><p>Because Drand emits a pulse every 30 seconds, a ~1% increase is added per 12-hour epoch (1440 rounds) to the base difficulty. This keeps the cost of registering names aligned with hardware improvements.</p><blockquote><p><strong>Note to Future Maintainers:</strong> If specialized VDF ASICs become cheap and widely available, the 300k ips baseline will break. If commodity ASICs push the baseline to 30M ips, the base iteration costs will need to be revised by a factor of 100x via a hard fork to maintain the same wall-clock delays.</p></blockquote>',14)])])}const m=a(r,[["render",n]]);export{p as __pageData,m as default};
